/** Browser interaction with the unchanged production factories and native primitives. */
async (page) => {
  const qa = page.context().pages().find(candidate => candidate.url().includes('/dataset-native-fixture/'))
  if (!qa) throw new Error('Build and open the native dataset fixture first')
  const assert = (value, message) => { if (!value) throw new Error(message) }, errors = [], onError = error => errors.push(error.message)
  qa.on('pageerror', onError)
  const datasets = qa.locator('.vc-datasets-workspace'), details = qa.locator('.vc-dataset-detail'), modal = qa.locator('.vc-profile-dialog'), overlay = modal.locator('.vc-dataset-generating-overlay'), card = qa.locator('.vc-reference-panel .vc-dataset-task-status')
  const aligned = () => datasets.locator('.vc-datasets-toolbar').evaluate(element => {
    const a = element.querySelector('.vc-datasets-search').getBoundingClientRect(), b = element.querySelector('.vc-select').getBoundingClientRect()
    return Math.abs(a.y + a.height / 2 - b.y - b.height / 2) < 1 && a.right <= b.left
  })
  const fits = locator => locator.evaluate(element => element.scrollWidth <= element.clientWidth + 1)
  const close = async () => { await qa.keyboard.press('Escape'); await details.waitFor({ state: 'hidden' }) }
  try {
    await qa.reload({ waitUntil: 'load' })
    await qa.setViewportSize({ width: 1440, height: 900 })
    await qa.getByRole('tab', { name: '数据集', exact: true }).click()
    assert(await aligned(), 'Desktop filters share one row')
    await datasets.locator('[data-dataset-row]').first().getByRole('button', { name: '详情', exact: true }).click()
    await details.locator('.vc-dataset-facts').first().waitFor()
    await details.getByRole('tab', { name: '视觉规则', exact: true }).click()
    assert(await details.locator('.vc-dataset-saved-rule').count() === 7, 'Seven frozen active rules')
    assert(await details.getByRole('checkbox').count() === 0, 'Saved rules are read-only')
    await details.getByRole('button', { name: '全部候选规则 · 14', exact: true }).click()
    assert(await details.locator('.vc-dataset-saved-rule').count() === 14, 'All fourteen saved candidates are inspectable')
    await details.getByRole('tab', { name: '逐图观察', exact: true }).click()
    assert(await details.locator('.vc-dataset-sample').count() === 10, 'Ten saved sample observations')
    await details.getByRole('tab', { name: '数据包内容', exact: true }).click()
    assert(await details.locator('.vc-dataset-file').count() === 5, 'Five checksummed saved files')
    await details.getByRole('tab', { name: '概览', exact: true }).click()
    for (const dark of [true, false]) {
      await qa.evaluate(dark => document.body.toggleAttribute('data-ds-dark-theme', dark), dark)
      assert(await fits(details), 'Details fit both themes')
      await details.screenshot({ path: `.playwright-mcp/dataset-workspace-detail-${dark ? 'dark' : 'light'}.png`, scale: 'css' })
    }
    await qa.setViewportSize({ width: 390, height: 844 })
    assert(await fits(details), 'Narrow details do not overflow')
    await details.screenshot({ path: '.playwright-mcp/dataset-workspace-detail-narrow.png', scale: 'css' }); await close()
    assert(await aligned() && await fits(datasets), 'Narrow filters remain horizontal without overflow')
    await datasets.screenshot({ path: '.playwright-mcp/dataset-workspace-list-narrow.png', scale: 'css' })
    await qa.setViewportSize({ width: 1440, height: 900 })
    for (const dark of [true, false]) {
      await qa.evaluate(dark => document.body.toggleAttribute('data-ds-dark-theme', dark), dark)
      await datasets.screenshot({ path: `.playwright-mcp/dataset-workspace-list-${dark ? 'dark' : 'light'}.png`, scale: 'css' })
    }
    await datasets.getByRole('textbox', { name: '搜索数据集名称、模型或 ID' }).fill('not-a-dataset')
    await datasets.getByText('没有符合筛选条件的数据集', { exact: true }).waitFor()
    await datasets.getByRole('button', { name: '清除筛选', exact: true }).click()
    await qa.evaluate(() => window.datasetQa.failReads(true)); await datasets.getByRole('button', { name: '刷新', exact: true }).click()
    await datasets.getByRole('alert').waitFor()
    assert(await datasets.locator('[data-dataset-row]').count() === 1, 'Read errors retain prior rows')
    await qa.evaluate(() => window.datasetQa.failReads(false)); await datasets.getByRole('button', { name: '刷新', exact: true }).click()
    await qa.getByRole('tab', { name: '参考与画像', exact: true }).click()
    await qa.locator('.vc-profile-dock').getByRole('button', { name: '查看完整档案', exact: true }).click()
    await modal.getByRole('button', { name: '生成数据集', exact: true }).click(); await overlay.waitFor()
    assert(await modal.locator('.vc-profile-workspace').evaluate(element => element.inert), 'The covered body is inert')
    assert(await overlay.locator('[role=progressbar]').getAttribute('aria-valuenow') === null, 'Unacknowledged requests have indeterminate progress')
    assert(await overlay.evaluate(element => { const box = element.getBoundingClientRect(), parent = element.parentElement.getBoundingClientRect(); return Math.abs(box.y - parent.y) < 1 && Math.abs(box.height - parent.height) < 1 && getComputedStyle(element).backgroundColor.endsWith('0.55)') }), 'The translucent mask covers only content')
    await modal.getByRole('button', { name: '关闭', exact: true }).last().click(); await modal.waitFor({ state: 'hidden' }); await card.waitFor()
    assert(await card.getAttribute('data-task-status') === 'submitting', 'Closing before acknowledgement retains submission')
    await qa.evaluate(async () => { await window.datasetQa.progress('running', 'samples', 3, 10); window.datasetQa.acknowledge() })
    await qa.waitForFunction(() => document.querySelector('.vc-reference-panel [role=progressbar]')?.getAttribute('aria-valuenow') === '3')
    await card.getByRole('button', { name: '查看完整档案', exact: true }).click(); await overlay.waitFor()
    assert(await overlay.locator('[role=progressbar]').getAttribute('aria-valuenow') === '3', 'Reopen preserves actual phase counts')
    await qa.evaluate(() => document.body.setAttribute('data-ds-dark-theme', '')); await modal.screenshot({ path: '.playwright-mcp/dataset-workspace-overlay-dark.png', scale: 'css' })
    await modal.getByRole('button', { name: '关闭', exact: true }).last().click()
    await qa.evaluate(() => window.datasetQa.progress('failed', 'files', 2, 5))
    await qa.waitForFunction(() => document.querySelector('.vc-reference-panel .vc-dataset-task-status')?.textContent.includes('生成已停止'))
    await qa.evaluate(() => window.datasetQa.progress('completed', 'saving', 1, 1))
    await qa.waitForFunction(() => document.querySelector('.vc-reference-panel .vc-dataset-task-status')?.textContent.includes('已生成'))
    await card.getByRole('button', { name: '查看数据集', exact: true }).click()
    assert(await datasets.locator('[data-dataset-row]').count() === 2 && await datasets.locator('.vc-dataset-task-status').count() === 0, 'One row per task/package without a duplicated card')
    await qa.evaluate(() => window.datasetQa.progress('running', 'samples', 4, 10)); await qa.getByRole('tab', { name: '参考与画像', exact: true }).click()
    await qa.emulateMedia({ reducedMotion: 'reduce' })
    assert(await card.locator('.vc-gallery-import-art img').evaluate(element => getComputedStyle(element).animationName === 'none'), 'Native loading artwork respects reduced motion')
    assert(await qa.evaluate(() => window.datasetQa.starts()) === 1 && errors.length === 0, 'One fixture generation and no page errors')
    return { mode: 'native-production-components', modelSettingsTable: true, horizontalFilters: ['desktop', '390px'], bodyOnlyMask: true, closeBeforeAcknowledgement: true, sameTaskOnReopen: true, phaseProgress: '3/10', readOnlyRules: 7, candidateRules: 14, samples: 10, files: 5, themes: ['dark', 'light'], narrowOverflow: false, retainedOnReadFailure: true, noDuplicateCard: true, reducedMotion: true, interceptedStarts: 1, productionWrites: 0, pageErrors: errors }
  } finally { qa.off('pageerror', onError) }
}
